<section class="step" data-step="publish"><div class="section-title"><span>STEP 8</span><h3>Verification & publish</h3></div><div class="publish-grid"><label class="choice-card"><input type="checkbox" name="verified" value="1" <?=$verified?'checked':''?>><b>✓ Verified business</b><span>Show verified trust status publicly.</span></label><label class="choice-card"><input type="checkbox" name="featured" value="1" <?=$featured?'checked':''?>><b>★ Featured business</b><span>Eligible for featured homepage/directory positions.</span></label><label>Status<select name="status"><?php $cur=(string)av($business,['status'],'active');foreach(['active','pending','inactive','published','approved'] as $s):?><option value="<?=$s?>" <?=$cur===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select></label><label class="full">Internal admin notes<textarea name="internal_notes" rows="4"><?=bm1140_h($business['_profile']['internal_notes']??'')?></textarea></label></div><div class="review-box"><h4>Before publishing</h4><ul><li>Shopkeeper/owner selected</li><li>Correct phone and WhatsApp</li><li>Accurate address/location</li><li>Real services and opening hours only</li><li>Good business image</li><li>Verify only after checks</li></ul></div></section>
